import{_ as t,o as e,c as d,Q as a}from"./chunks/framework.48927342.js";const g=JSON.parse('{"title":"Dates, Weekdays, Months, and Seasons","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/07-dates.md","filePath":"en/more/maltese/grammar/07-dates.md"}'),r={name:"en/more/maltese/grammar/07-dates.md"},i=a('<h1 id="dates-weekdays-months-and-seasons" tabindex="-1">Dates, Weekdays, Months, and Seasons <a class="header-anchor" href="#dates-weekdays-months-and-seasons" aria-label="Permalink to &quot;Dates, Weekdays, Months, and Seasons&quot;">​</a></h1><h2 id="_1-days-of-the-week" tabindex="-1">1. Days of the Week <a class="header-anchor" href="#_1-days-of-the-week" aria-label="Permalink to &quot;1. Days of the Week&quot;">​</a></h2><table><thead><tr><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>Monday</td><td>it-Tnejn</td></tr><tr><td>Tuesday</td><td>it-Tlieta</td></tr><tr><td>Wednesday</td><td>l-Erbgħa</td></tr><tr><td>Thursday</td><td>il-Ħamis</td></tr><tr><td>Friday</td><td>il-Ġimgħa</td></tr><tr><td>Saturday</td><td>is-Sibt</td></tr><tr><td>Sunday</td><td>il-Ħadd</td></tr></tbody></table><p><code>nhar</code> (day) is often used before a weekday, for example <code>nhar it-Tnejn</code> (on Monday). The definite article is commonly retained.</p><h2 id="_2-months" tabindex="-1">2. Months <a class="header-anchor" href="#_2-months" aria-label="Permalink to &quot;2. Months&quot;">​</a></h2><table><thead><tr><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>January</td><td>Jannar</td></tr><tr><td>February</td><td>Frar</td></tr><tr><td>March</td><td>Marzu</td></tr><tr><td>April</td><td>April</td></tr><tr><td>May</td><td>Mejju</td></tr><tr><td>June</td><td>Ġunju</td></tr><tr><td>July</td><td>Lulju</td></tr><tr><td>August</td><td>Awwissu</td></tr><tr><td>September</td><td>Settembru</td></tr><tr><td>October</td><td>Ottubru</td></tr><tr><td>November</td><td>Novembru</td></tr><tr><td>December</td><td>Diċembru</td></tr></tbody></table><p><code>f&#39;</code> is commonly used before a month: <code>f&#39;Mejju</code> (in May), <code>f&#39;Ġunju</code> (in June). Month names are written as regular nouns in sentences; they are capitalized uniformly here for lookup.</p><h2 id="_3-seasons-years-and-relative-dates" tabindex="-1">3. Seasons, Years, and Relative Dates <a class="header-anchor" href="#_3-seasons-years-and-relative-dates" aria-label="Permalink to &quot;3. Seasons, Years, and Relative Dates&quot;">​</a></h2><table><thead><tr><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>spring</td><td>rebbiegħa</td></tr><tr><td>summer</td><td>sajf</td></tr><tr><td>autumn; fall</td><td>ħarifa</td></tr><tr><td>winter</td><td>xitwa</td></tr><tr><td>year</td><td>sena</td></tr><tr><td>next year</td><td>is-sena d-dieħla</td></tr><tr><td>last year</td><td>is-sena l-oħra</td></tr></tbody></table><p>Common forms with seasons include <code>fir-rebbiegħa</code> (in spring), <code>fis-sajf</code> (in summer), <code>fil-ħarifa</code> (in autumn), and <code>fix-xitwa</code> (in winter). Years can be written numerically, for example <code>fl-2026</code> (in 2026).</p><h3 id="last-this-next-week-month-and-year" tabindex="-1">Last/This/Next Week, Month, and Year <a class="header-anchor" href="#last-this-next-week-month-and-year" aria-label="Permalink to &quot;Last/This/Next Week, Month, and Year&quot;">​</a></h3><table><thead><tr><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>last week</td><td>il-ġimgħa li għaddiet</td></tr><tr><td>this week</td><td>din il-ġimgħa</td></tr><tr><td>next week</td><td>il-ġimgħa d-dieħla</td></tr><tr><td>last month</td><td>ix-xahar li għadda</td></tr><tr><td>this month</td><td>dan ix-xahar</td></tr><tr><td>next month</td><td>ix-xahar id-dieħel</td></tr><tr><td>last year</td><td>is-sena l-oħra</td></tr><tr><td>this year</td><td>din is-sena</td></tr><tr><td>next year</td><td>is-sena d-dieħla</td></tr></tbody></table><p><code>li għadda</code> means “that has just passed/last,” <code>li jmiss</code> can mean “next,” and <code>d-dieħel</code> is often used for a coming month or year. Interpret relative time expressions together with the tense and context.</p><h2 id="_4-date-formats" tabindex="-1">4. Date Formats <a class="header-anchor" href="#_4-date-formats" aria-label="Permalink to &quot;4. Date Formats&quot;">​</a></h2><p>Before weekdays, months, and seasons, prepositions often contract with the definite article. A common date order is “day + <code>ta&#39;</code> + month + year,” for example <code>14 ta&#39; Ottubru 2026</code> (14 October 2026). Use <code>nhar</code> to introduce a weekday, as in <code>nhar it-Tnejn</code> (on Monday). To avoid ambiguity between day/month conventions, write the month name in full in formal itineraries. Relative week, month, and year phrases are listed above.</p><h2 id="_5-twenty-date-examples" tabindex="-1">5. Twenty Date Examples <a class="header-anchor" href="#_5-twenty-date-examples" aria-label="Permalink to &quot;5. Twenty Date Examples&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>On Monday I go to school.</td><td>Nhar it-Tnejn immur l-iskola.</td></tr><tr><td style="text-align:right;">2</td><td>On Tuesday I work at home.</td><td>Nhar it-Tlieta naħdem id-dar.</td></tr><tr><td style="text-align:right;">3</td><td>On Wednesday I read a book.</td><td>Nhar l-Erbgħa naqra ktieb.</td></tr><tr><td style="text-align:right;">4</td><td>On Thursday I buy bread.</td><td>Nhar il-Ħamis nixtri l-ħobż.</td></tr><tr><td style="text-align:right;">5</td><td>On Friday I meet a friend.</td><td>Nhar il-Ġimgħa niltaqa&#39; ma&#39; ħabib.</td></tr><tr><td style="text-align:right;">6</td><td>On Saturday I go to the beach.</td><td>Nhar is-Sibt immur il-bajja.</td></tr><tr><td style="text-align:right;">7</td><td>On Sunday I rest.</td><td>Nhar il-Ħadd nistrieħ.</td></tr><tr><td style="text-align:right;">8</td><td>In January I wear a coat.</td><td>F&#39;Jannar nilbes kowt.</td></tr><tr><td style="text-align:right;">9</td><td>February has twenty-eight days.</td><td>Frar għandu tmienja u għoxrin jum.</td></tr><tr><td style="text-align:right;">10</td><td>Spring begins in March.</td><td>F&#39;Marzu tibda r-rebbiegħa.</td></tr><tr><td style="text-align:right;">11</td><td>In April we see flowers.</td><td>F&#39;April naraw il-fjuri.</td></tr><tr><td style="text-align:right;">12</td><td>In May I visit my family.</td><td>F&#39;Mejju nżur lill-familja tiegħi.</td></tr><tr><td style="text-align:right;">13</td><td>Summer begins in June.</td><td>F&#39;Ġunju jibda s-sajf.</td></tr><tr><td style="text-align:right;">14</td><td>In July I go to Malta.</td><td>F&#39;Lulju mmur Malta.</td></tr><tr><td style="text-align:right;">15</td><td>In December we celebrate Christmas.</td><td>F&#39;Diċembru niċċelebraw il-Milied.</td></tr><tr><td style="text-align:right;">16</td><td>I will start lessons on 14 October 2026.</td><td>Nibda l-lezzjonijiet fl-14 ta&#39; Ottubru 2026.</td></tr><tr><td style="text-align:right;">17</td><td>I visited my family last week.</td><td>Il-ġimgħa li għaddiet żort lill-familja tiegħi.</td></tr><tr><td style="text-align:right;">18</td><td>We are studying at home this week.</td><td>Din il-ġimgħa qed nitgħallmu d-dar.</td></tr><tr><td style="text-align:right;">19</td><td>I am going to Malta next month.</td><td>Ix-xahar id-dieħel immur Malta.</td></tr><tr><td style="text-align:right;">20</td><td>We will move house next year.</td><td>Is-sena d-dieħla se niċċaqilqu.</td></tr></tbody></table>',17),n=[i];function s(o,l,h,m,y,u){return e(),d("div",null,n)}const b=t(r,[["render",s]]);export{g as __pageData,b as default};
